    [16791]={name="Silkstream Cuffs",quality=2,ilvl=38,sourceType="quest_reward",instructions="Reward from the quest 'Book of the Ancients'. Pick it over the other reward choices.",zone="Desolace",questName="Book of the Ancients",lore="I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."},
