    [19115]={name="Flask of Forest Mojo",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Return to Primal Torntusk'. Pick it over the other reward choices.",zone="The Hinterlands",questName="Return to Primal Torntusk",lore="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."},
    [19116]={name="Greenleaf Handwraps",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Separation Anxiety'. Pick it over the other reward choices.",zone="The Hinterlands",questName="Separation Anxiety",lore="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."},
    [19118]={name="Nature's Breath",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Dark Vessels'.",zone="The Hinterlands",questName="Dark Vessels",lore="The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."},
    [19121]={name="Deep Woodlands Cloak",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Vile Priestess Hexx and Her Minions'. Pick it over the other reward choices.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
